begin;
select no_plan();
select set_config('test.actor','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true);
select set_config('test.workspace','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',true);
insert into public.platform_access_assignments values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','owner','platform',null,now()-interval '1 day',null);
select set_config('request.jwt.claims',jsonb_build_object('aal','aal2','amr',jsonb_build_array(jsonb_build_object('method','totp','timestamp',floor(extract(epoch from clock_timestamp())))))::text,true);
set local role authenticated;
select lives_ok($$select public.create_sandbox_subscription_fiscal_policy('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','123',now()+interval '1 day')$$,'owner creates modeled policy');
select lives_ok($$select public.create_sandbox_subscription_fiscal_policy('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','123',now()+interval '1 day')$$,'policy retry succeeds');
select throws_ok($$select public.create_sandbox_subscription_fiscal_policy('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','456',now()+interval '1 day')$$,'22023','fiscal policy command conflict','changed policy retry rejected');
reset role;
select is((select count(*) from public.billing_fiscal_policy_models),1::bigint,'one model');
select is((select count(*) from public.billing_fiscal_policy_audit),1::bigint,'one audited policy');
select set_config('request.jwt.claims','{"aal":"aal2","amr":[{"method":"totp","timestamp":1}]}',true);
set local role authenticated;
select throws_ok($$select public.create_sandbox_subscription_fiscal_policy('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','123',now()+interval '1 day')$$,'42501','recent platform MFA required','MFA rechecked on retry');
reset role;
select set_config('test.actor','dddddddd-dddd-4ddd-8ddd-dddddddddddd',true);
set local role authenticated;
select throws_ok($$select public.create_sandbox_subscription_fiscal_policy('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','123',now()+interval '1 day')$$,'42501','platform owner required','non-owner denied');
reset role;
select set_config('test.actor','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true);
select set_config('request.jwt.claims',jsonb_build_object('aal','aal2','amr',jsonb_build_array(jsonb_build_object('method','totp','timestamp',floor(extract(epoch from clock_timestamp())))))::text,true);
insert into public.billing_fiscal_policies(id,environment,shop_id,effective_at,vat_code,payment_subject,payment_mode)
 values('22222222-2222-4222-8222-222222222222','sandbox','123',now()-interval '1 hour',1,'service','full_payment');
insert into public.billing_sandbox_orders values('11111111-1111-4111-8111-111111111111','123',99000,'RUB','reserved',null,'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',now(),now()+interval '1 month');
set local role authenticated;
select lives_ok($$select public.prepare_sandbox_receipt('11111111-1111-4111-8111-111111111111','buyer@example.test')$$,'legacy prepares before model is effective');
select throws_ok($$select public.create_sandbox_subscription_fiscal_policy('22222222-2222-4222-8222-222222222222','123',now()-interval '1 hour')$$,'22023','fiscal policy command conflict','cannot attach model to legacy policy');
reset role;
select is((select count(*) from public.billing_subscription_fiscal_terms),0::bigint,'legacy snapshot gets no inferred terms');
create temp table saved_legacy as select to_jsonb(s)::text body from public.billing_receipt_snapshots s;
select set_config('test.effective',(clock_timestamp()+interval '2 seconds')::text,true);
set local role authenticated;
select lives_ok($$select public.create_sandbox_subscription_fiscal_policy('33333333-3333-4333-8333-333333333333','123',current_setting('test.effective')::timestamptz)$$,'new activation prepared');
reset role;
select pg_sleep(2.1);
insert into public.billing_sandbox_orders values('44444444-4444-4444-8444-444444444444','123',99000,'RUB','reserved',null,'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',now(),now()+interval '1 month');
-- A more recent legacy policy must not override a deliberate model activation.
insert into public.billing_fiscal_policies(id,environment,shop_id,effective_at,vat_code,payment_subject,payment_mode)
 values('55555555-5555-4555-8555-555555555555','sandbox','123',clock_timestamp()-interval '1 millisecond',2,'property_right','full_payment');
set local role authenticated;
select lives_ok($$select public.prepare_sandbox_receipt('44444444-4444-4444-8444-444444444444','buyer@example.test')$$,'same RPC atomically prepares modeled receipt');
select is((select item->>'display_status' from jsonb_array_elements(public.list_sandbox_fiscal_policies('123')->'items') item where item->>'id'='33333333-3333-4333-8333-333333333333'),'current','policy list agrees with actual subscription selection');
select is((select item->>'display_status' from jsonb_array_elements(public.list_sandbox_fiscal_policies('123')->'items') item where item->>'id'='55555555-5555-4555-8555-555555555555'),'superseded','newer legacy policy is not shown as current');

select lives_ok($$select public.prepare_sandbox_receipt('44444444-4444-4444-8444-444444444444','buyer@example.test')$$,'modeled retry succeeds');
select throws_ok($$select public.prepare_sandbox_receipt('44444444-4444-4444-8444-444444444444','changed@example.test')$$,'22023','receipt command conflict','changed retry rejected');
select lives_ok($$select public.prepare_sandbox_receipt('11111111-1111-4111-8111-111111111111','buyer@example.test')$$,'legacy retry succeeds after activation');
reset role;
select is((select policy_id from public.billing_receipt_snapshots where order_id='44444444-4444-4444-8444-444444444444'),'33333333-3333-4333-8333-333333333333'::uuid,'subscription model selected instead of newer legacy rights policy');
select is((select count(*) from public.billing_subscription_fiscal_terms),1::bigint,'one terms row despite retry');
select is((select count(*) from public.billing_receipt_audit),2::bigint,'one audit per order');
select is((select to_jsonb(s)::text from public.billing_receipt_snapshots s where order_id='11111111-1111-4111-8111-111111111111'),(select body from saved_legacy),'legacy bytes unchanged');
select set_config('test.workspace','cccccccc-cccc-4ccc-8ccc-cccccccccccc',true);
set local role authenticated;
select throws_ok($$select public.prepare_sandbox_receipt('44444444-4444-4444-8444-444444444444','buyer@example.test')$$,'42501','receipt access denied','revoked workspace access rejected on retry');
reset role;
select set_config('test.workspace','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',true);
select set_config('test.actor','dddddddd-dddd-4ddd-8ddd-dddddddddddd',true);
set local role authenticated;
select throws_ok($$select public.prepare_sandbox_receipt('44444444-4444-4444-8444-444444444444','buyer@example.test')$$,'42501','receipt access denied','other buyer denied');
select throws_ok($$select public.select_subscription_fiscal_policy('123',now())$$,'42501',null,'internal selector not exposed');
reset role;
select set_config('test.actor','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true);
insert into public.billing_sandbox_orders values('66666666-6666-4666-8666-666666666666','123',99000,'RUB','reserved',null,'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',now(),now()-interval '1 month');
set local role authenticated;
select throws_ok($$select public.prepare_sandbox_receipt('66666666-6666-4666-8666-666666666666','buyer@example.test')$$,'23514',null,'invalid period fails entire RPC');
reset role;
select is((select count(*) from public.billing_receipt_snapshots where order_id='66666666-6666-4666-8666-666666666666'),0::bigint,'failed RPC leaves no snapshot');
select is((select count(*) from public.billing_receipt_audit where order_id='66666666-6666-4666-8666-666666666666'),0::bigint,'failed RPC leaves no audit');
select is((select count(*) from public.billing_subscription_fiscal_terms where order_id='66666666-6666-4666-8666-666666666666'),0::bigint,'failed RPC leaves no terms');
set local role anon;
select throws_ok($$select public.create_sandbox_subscription_fiscal_policy(null,'123',now())$$,'42501',null,'anonymous policy creation denied');
select throws_ok($$select public.prepare_sandbox_receipt('44444444-4444-4444-8444-444444444444','buyer@example.test')$$,'42501',null,'anonymous receipt denied');
reset role;
select * from finish();
rollback;
